package cn.mop.adapters.backup;
import cn.mop.domain.DomainException;
import cn.mop.adapters.backup.BackupEnvelopeEncryption.*;
import static cn.mop.adapters.backup.BackupArchiveFixture.*;
import org.junit.jupiter.api.Test;
import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
class BackupEnvelopeArchiveTest {
 static class Memory implements BackupEnvelopeArchive.ObjectStore {Map<String,byte[]> values=new HashMap<>();int puts,reads;boolean ready=true,loseReply;String key(Scope s){return s.tenantId()+"/"+s.versionId();}public boolean ready(){return ready;}public void storeImmutable(Envelope e){puts++;byte[] old=values.putIfAbsent(key(e.scope()),e.encoded());if(old!=null&&!Arrays.equals(old,e.encoded()))throw new RuntimeException("SYNTHETIC_CONFLICT");if(loseReply)throw new RuntimeException("SYNTHETIC_LOST_RESPONSE");}public byte[] read(Scope s,long bytes,String hash){reads++;byte[] value=values.get(key(s));if(value==null)throw new RuntimeException("SYNTHETIC_MISSING");return value.clone();}}
 @Test void storeAuthenticatesBeforeWritingAndReadsBackBeforeReceipt(){var keys=new Keys();var crypto=crypto(keys);var store=new Memory();var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var receipt=new BackupEnvelopeArchive(crypto,store,(a,x,o)->true).store(ACCESS,s,e);assertEquals(1,store.puts);assertEquals(1,store.reads);assertEquals(2,keys.unwraps);assertEquals(e.sha256(),receipt.encryptedObjectSha256());assertEquals(e.encoded().length,receipt.encryptedObjectBytes());assertTrue(receipt.currentObjectBytesAndAeadVerified());assertFalse(receipt.versionRegistered());assertFalse(receipt.backupRunCompleted());assertFalse(receipt.retentionVerified());}
 @Test void unknownWriteOnlyReconcilesOriginalObjectWithoutAnotherPut(){var keys=new Keys();var crypto=crypto(keys);var store=new Memory();store.loseReply=true;var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->true);var ex=assertThrows(DomainException.class,()->archive.store(ACCESS,s,e));assertEquals("BACKUP_ARCHIVE_WRITE_UNCONFIRMED",ex.code);assertEquals(1,store.puts);assertEquals(0,store.reads);var receipt=archive.verifyExisting(ACCESS,s,e.encoded().length,e.sha256());assertEquals(e.sha256(),receipt.encryptedObjectSha256());assertEquals(1,store.puts);assertEquals(1,keys.creates);}
 @Test void failedReadCannotProveOriginalWriteDidNotCommit(){var keys=new Keys();var crypto=crypto(keys);var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var store=new Memory(){@Override public byte[] read(Scope x,long b,String h){throw new RuntimeException("secret=never-expose");}};var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->true);assertEquals("BACKUP_ARCHIVE_WRITE_UNCONFIRMED",assertThrows(DomainException.class,()->archive.store(ACCESS,s,e)).code);assertTrue(store.values.containsKey(store.key(s)));var ex=assertThrows(DomainException.class,()->archive.verifyExisting(ACCESS,s,e.encoded().length,e.sha256()));assertEquals(503,ex.status);assertNull(ex.getCause());assertFalse(ex.getMessage().contains("never-expose"));}
 @Test void forgedEnvelopeNeverReachesStore(){var keys=new Keys();var crypto=crypto(keys);var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);byte[] body=e.ciphertext();body[0]^=1;var store=new Memory();var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->true);assertThrows(DomainException.class,()->archive.store(ACCESS,s,new Envelope(s,e.keyReference(),e.wrappedKey(),e.nonce(),body)));assertEquals(0,store.puts);}
 @Test void digestAndAeadAreBothCheckedForReadback(){var keys=new Keys();var crypto=crypto(keys);var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var store=new Memory(){@Override public byte[] read(Scope x,long n,String h){byte[] bytes=super.read(x,n,h);bytes[bytes.length-1]^=1;return bytes;}};assertEquals("BACKUP_ARCHIVE_WRITE_UNCONFIRMED",assertThrows(DomainException.class,()->new BackupEnvelopeArchive(crypto,store,(a,x,o)->true).store(ACCESS,s,e)).code);}
 @Test void unavailableStorePreventsKeyUnwrapAndPut(){var keys=new Keys();var crypto=crypto(keys);var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var store=new Memory();store.ready=false;assertThrows(DomainException.class,()->new BackupEnvelopeArchive(crypto,store,(a,x,o)->true).store(ACCESS,s,e));assertEquals(0,keys.unwraps);assertEquals(0,store.puts);}
 @Test void initialDenialAndCrossTenantNeverTouchTheProvider(){var keys=new Keys();var crypto=crypto(keys);var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var store=new Memory();var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->false);assertEquals(403,assertThrows(DomainException.class,()->archive.store(ACCESS,s,e)).status);assertEquals(404,assertThrows(DomainException.class,()->archive.store(new Access(UUID.randomUUID(),ACCESS.actorId(),1),s,e)).status);assertEquals(0,store.puts);assertEquals(0,keys.unwraps);}
 @Test void revocationBeforePutDoesNotDispatch(){var keys=new Keys();var crypto=crypto(keys);var store=new Memory();var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var count=new AtomicInteger();var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->count.incrementAndGet()==1);assertEquals(403,assertThrows(DomainException.class,()->archive.store(ACCESS,s,e)).status);assertEquals(0,store.puts);}
 @Test void revocationAfterPutIsUnconfirmedNotDefinitivelyRejected(){var keys=new Keys();var crypto=crypto(keys);var store=new Memory();var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var count=new AtomicInteger();var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->count.incrementAndGet()<3);assertEquals("BACKUP_ARCHIVE_WRITE_UNCONFIRMED",assertThrows(DomainException.class,()->archive.store(ACCESS,s,e)).code);assertEquals(1,store.puts);assertTrue(store.values.containsKey(store.key(s)));}
 @Test void verifyRequiresIndependentCurrentReadAuthorization(){var keys=new Keys();var crypto=crypto(keys);var store=new Memory();var s=scope();var e=crypto.seal(ACCESS,s,PLAIN);var archive=new BackupEnvelopeArchive(crypto,store,(a,x,o)->o==BackupEnvelopeArchive.Operation.STORE);archive.store(ACCESS,s,e);int reads=store.reads;assertEquals(403,assertThrows(DomainException.class,()->archive.verifyExisting(ACCESS,s,e.encoded().length,e.sha256())).status);assertEquals(reads,store.reads);}
 @Test void referencesAreBoundedAndDependenciesMandatory(){var keys=new Keys();var crypto=crypto(keys);var store=new Memory();assertThrows(NullPointerException.class,()->new BackupEnvelopeArchive(null,store,(a,s,o)->true));assertThrows(NullPointerException.class,()->new BackupEnvelopeArchive(crypto,null,(a,s,o)->true));assertThrows(NullPointerException.class,()->new BackupEnvelopeArchive(crypto,store,null));var archive=new BackupEnvelopeArchive(crypto,store,(a,s,o)->true);assertThrows(DomainException.class,()->archive.verifyExisting(ACCESS,scope(),Long.MAX_VALUE,"a".repeat(64)));assertThrows(DomainException.class,()->archive.verifyExisting(ACCESS,scope(),1,"bad"));assertEquals(0,store.reads);}
}
